static uint64_t now_ms(void){int64_t v=esp_timer_get_time();return v<0?UINT64_MAX:(uint64_t)v/1000;}
static uint32_t u32(const uint8_t*p){return (uint32_t)p[0]<<24|(uint32_t)p[1]<<16|(uint32_t)p[2]<<8|p[3];}
static void put32(uint8_t*p,uint32_t n){for(unsigned i=0;i<4;i++)p[3-i]=(uint8_t)(n>>(8*i));}
static uint64_t now_cb(void*unused){(void)unused;return now_ms();}
static int current(void *unused){(void)unused;return config.current&&config.current()==1;}
static uint32_t generation_cb(void*unused){(void)unused;return config.generation?config.generation():0;}
static int same_authority(void){return current(NULL)&&generation_cb(NULL)&&engine.authority_generation==generation_cb(NULL);}
static int random_cb(void*unused,uint8_t*p,size_t n){(void)unused;return gb_crypto_random(p,n);}
static int random_mbed(void*unused,uint8_t*p,size_t n){return random_cb(unused,p,n)?0:MBEDTLS_ERR_ECP_RANDOM_FAILED;}
static int hash_cb(void*unused,const uint8_t*p,size_t n,uint8_t out[32]){(void)unused;return gb_crypto_hash(p,n,out);}
static int owner_verify(void*unused,const uint8_t*p,size_t n,const uint8_t*s,size_t z){(void)unused;return current(NULL)&&ag_crypto_verify(config.owner_der,config.owner_bytes,config.owner_pin,p,n,s,z)&&current(NULL);}
