static int sign_cb(void*unused,const uint8_t*p,size_t n,uint8_t s[72],size_t*z){(void)unused;return gb_crypto_sign(p,n,s,z);}
static int ephemeral_cb(void*unused,uint8_t p[65]){(void)unused;size_t n=0;mbedtls_ecp_keypair_free(&ephemeral_key);mbedtls_ecp_keypair_init(&ephemeral_key);return !mbedtls_ecp_gen_key(MBEDTLS_ECP_DP_SECP256R1,&ephemeral_key,random_mbed,NULL)&&!mbedtls_ecp_point_write_binary(&ephemeral_key.MBEDTLS_PRIVATE(grp),&ephemeral_key.MBEDTLS_PRIVATE(Q),MBEDTLS_ECP_PF_UNCOMPRESSED,&n,p,65)&&n==65;}
